<script>
  (function () {
    /* Páginas de destino: cámbialas si tus URLs son otras */
    var RM_LINKS = {
      planes: '/planes-y-presupuestos/',
      web: '/diseno-web/',
      tienda: '/tienda-online/',
      marketing: '/marketing-digital/',
      ayudas: '/subvenciones/',
      llamada: '/reserva-una-cita/'
    };

    /* Mensaje según la categoría (clave = slug de la categoría) */
    var RM_CTA = {
      'diseno-web': {
        eyebrow: 'Diseño web',
        title: '¿Quieres una web que <em>explique bien</em> lo que haces?',
        text: 'Diseñamos tu web en WordPress, adaptada al móvil y preparada para aparecer en Google. Con mantenimiento incluido.',
        label: 'Ver planes de web',
        url: RM_LINKS.web
      },
      'tienda-online': {
        eyebrow: 'Tienda online',
        title: 'Tu tienda online, lista para <em>vender</em>',
        text: 'WooCommerce, diseño a medida y pasarelas de pago, todo listo para vender sin complicaciones técnicas.',
        label: 'Quiero mi tienda online',
        url: RM_LINKS.tienda
      },
      'marketing-digital': {
        eyebrow: 'Marketing digital',
        title: '¿Te ayudamos a que te <em>encuentren</em>?',
        text: 'SEO local, redes sociales y contenidos pensados para negocios de Castellón. Con objetivos claros y precio cerrado.',
        label: 'Ver planes de marketing',
        url: RM_LINKS.marketing
      },
      'transformacion-digital': {
        eyebrow: 'Ayudas y Kit Digital',
        title: '¿Puedes pedir una <em>ayuda</em> para tu web?',
        text: 'Revisamos contigo qué ayudas de digitalización están abiertas y si tu negocio encaja, sin compromiso.',
        label: 'Ver subvenciones',
        url: RM_LINKS.ayudas
      }
    };

    function run() {
      /* Un único sitio para las URLs: también la CTA de la barra lateral */
      document.querySelectorAll('.rm-post-cta__btn--secondary, .rm-post-aside__cta-btn').forEach(function (a) {
        a.href = RM_LINKS.llamada;
      });

      var cta = document.querySelector('.rm-post-cta');
      if (cta) cta.querySelector('.rm-post-cta__btn--primary').href = RM_LINKS.planes;

      var meta = document.querySelector('.rm-post-title .et_pb_title_meta_container');
      if (!cta || !meta) return;

      var cats = meta.querySelectorAll('a[rel~="tag"], a[rel~="category"]');
      var pick = null;
      for (var i = 0; i < cats.length && !pick; i++) {
        var m = cats[i].href.match(/\/category\/(?:[^\/]+\/)*([^\/?#]+)\/?/);
        if (m && RM_CTA[m[1]]) pick = RM_CTA[m[1]];
      }
      if (!pick) return;

      cta.querySelector('.rm-post-cta__eyebrow').textContent = pick.eyebrow;
      cta.querySelector('.rm-post-cta__title').innerHTML = pick.title;
      cta.querySelector('.rm-post-cta__text').textContent = pick.text;
      cta.querySelector('.rm-post-cta__primary-label').textContent = pick.label;
      cta.querySelector('.rm-post-cta__btn--primary').href = pick.url;
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', run);
    } else {
      run();
    }
  })();
</script>
