<script>
  (function () {
  function run() {
    var content = document.querySelector('.rm-post-content');
    var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    /* ---------- Barra lateral fija ---------- */
    var aside = document.querySelector('.rm-post-aside');
    var holder = aside && aside.closest('.et_pb_module');
    if (holder) holder.classList.add('rm-post-aside-sticky');

    /* ---------- Índice automático ---------- */
    var toc = document.querySelector('.rm-post-toc');
    var headings = content ? content.querySelectorAll('h2, h3') : [];
    var links = [];

    function slugify(text, i) {
      var s = text.toLowerCase()
        .normalize('NFD').replace(/[̀-ͯ]/g, '')
        .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
      return (s || 'seccion') + '-' + i;
    }

    function buildList() {
      var ol = document.createElement('ol');
      ol.className = 'rm-post-toc__list';
      headings.forEach(function (h) {
        var li = document.createElement('li');
        if (h.tagName === 'H3') li.className = 'is-sub';
        var a = document.createElement('a');
        a.href = '#' + h.id;
        a.textContent = h.textContent.trim();
        li.appendChild(a);
        ol.appendChild(li);
      });
      return ol;
    }

    if (content && headings.length >= 2) {
      headings.forEach(function (h, i) {
        if (!h.id) h.id = slugify(h.textContent, i + 1);
      });

      if (toc) {
        var list = toc.querySelector('.rm-post-toc__list');
        list.parentNode.replaceChild(buildList(), list);
        toc.hidden = false;
        links = Array.prototype.slice.call(toc.querySelectorAll('a'));
      }

      /* Versión desplegable al principio del artículo (tablet/móvil) */
      var inline = document.createElement('details');
      inline.className = 'rm-post-toc-inline';
      var summary = document.createElement('summary');
      summary.textContent = 'En este artículo';
      inline.appendChild(summary);
      inline.appendChild(buildList());
      var target = content.querySelector('.et_pb_post_content_inner') || content;
      target.insertBefore(inline, target.firstChild);
    }

    /* ---------- Barra de progreso ---------- */
    if (content && !document.querySelector('.rm-post-progress')) {
      var bar = document.createElement('div');
      bar.className = 'rm-post-progress';
      bar.setAttribute('aria-hidden', 'true');
      var fill = document.createElement('span');
      bar.appendChild(fill);
      document.body.appendChild(bar);

      var ticking = false;
      function update() {
        var rect = content.getBoundingClientRect();
        var total = rect.height - window.innerHeight * 0.6;
        var done = Math.min(1, Math.max(0, -rect.top / (total > 0 ? total : 1)));
        fill.style.transform = 'scaleX(' + done + ')';

        /* Resalta en el índice el apartado que se está leyendo */
        if (links.length) {
          var current = null;
          headings.forEach(function (h) {
            if (h.getBoundingClientRect().top < 140) current = h.id;
          });
          links.forEach(function (l) {
            l.classList.toggle('is-active', l.getAttribute('href') === '#' + current);
          });
        }
        ticking = false;
      }
      window.addEventListener('scroll', function () {
        if (!ticking) {
          ticking = true;
          window.requestAnimationFrame(update);
        }
      }, { passive: true });
      update();
    }

    /* ---------- Compartir ---------- */
    var url = window.location.href.split('#')[0];
    var titleEl = document.querySelector('.rm-post-title .entry-title');
    var title = (titleEl ? titleEl.textContent : document.title).trim();
    var shareUrls = {
      whatsapp: 'https://wa.me/?text=' + encodeURIComponent(title + ' ' + url),
      linkedin: 'https://www.linkedin.com/sharing/share-offsite/?url=' + encodeURIComponent(url),
      facebook: 'https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(url)
    };

    document.querySelectorAll('[data-rm-share]').forEach(function (el) {
      var type = el.getAttribute('data-rm-share');
      if (shareUrls[type]) {
        el.href = shareUrls[type];
        el.target = '_blank';
        el.rel = 'noopener';
      } else if (type === 'copy') {
        el.addEventListener('click', function () {
          function done() {
            el.classList.add('is-copied');
            setTimeout(function () { el.classList.remove('is-copied'); }, 1600);
          }
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(url).then(done);
          } else {
            var tmp = document.createElement('input');
            tmp.value = url;
            document.body.appendChild(tmp);
            tmp.select();
            document.execCommand('copy');
            document.body.removeChild(tmp);
            done();
          }
        });
      }
    });

    /* Desplazamiento suave al pulsar en el índice */
    if (!reduceMotion) {
      document.querySelectorAll('.rm-post-toc__list a').forEach(function (a) {
        a.addEventListener('click', function (e) {
          var target = document.getElementById(a.getAttribute('href').slice(1));
          if (!target) return;
          e.preventDefault();
          target.scrollIntoView({ behavior: 'smooth', block: 'start' });
          history.replaceState(null, '', a.getAttribute('href'));
        });
      });
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', run);
  } else {
    run();
  }
  })();
</script>
