<script>
  (function () {
    function run() {
      var grid = document.querySelector('.rm-post-related .rm-blog-grid');
      if (!grid) return;

      var here = window.location.href.split(/[?#]/)[0].replace(/\/$/, '');
      var posts = Array.prototype.slice.call(grid.querySelectorAll('.et_pb_post'));

      /* Orden original de Divi (et_pb_blog_item_X_N) */
      function index(el) {
        var m = el.className.match(/et_pb_blog_item_\d+_(\d+)/);
        return m ? parseInt(m[1], 10) : 0;
      }
      posts.sort(function (a, b) { return index(a) - index(b); });

      var shown = 0;
      posts.forEach(function (post) {
        var link = post.querySelector('.entry-title a');
        var url = link ? link.href.split(/[?#]/)[0].replace(/\/$/, '') : '';
        if (url === here || shown >= 3) {
          post.classList.add('rm-is-hidden');
        } else {
          post.style.order = shown;
          shown++;
        }
      });

      /* Sin otros artículos en la categoría: se oculta la sección */
      if (!shown) {
        var section = grid.closest('.rm-post-related');
        if (section) section.style.display = 'none';
      }
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', run);
    } else {
      run();
    }
  })();
</script>
